input.content:
// Follow-up gate for the customer-support assistant (WhatsApp Business + SMS).
// In-memory only: state is lost on process restart.
//
// Rules, checked in this order by check():
//   1. opted-out         customer sent a STOP keyword and has not sent START since
//   2. no-prior-inbound  customer has never written to us, so no proactive contact
//   3. outside-24h-window freeform text only inside 24h of the customer's last message
//      (templates are exempt from the window)

const WINDOW_MS = 24 * 60 * 60 * 1000;

// Whole-message keywords only, as used by carriers (CTIA) and WhatsApp.
// Ordinary sentences that merely contain one of these words do not match.
const STOP_KEYWORDS = new Set([
  'stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit',
]);
const START_KEYWORDS = new Set(['start', 'unstop', 'yes']);

const TYPES = new Set(['freeform', 'template']);

/** @type {Map<string, { optedOut: boolean, lastInbound: number | null }>} */
const customers = new Map();

function getCustomer(userId) {
  let c = customers.get(userId);
  if (!c) {
    c = { optedOut: false, lastInbound: null };
    customers.set(userId, c);
  }
  return c;
}

// Trim spaces, punctuation and emoji around the word, ignore case and
// invisible characters, and collapse inner whitespace.
function normalize(text) {
  return text
    .normalize('NFKC')
    .replace(/\p{Cf}/gu, '')
    .toLowerCase()
    .replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, '')
    .replace(/\s+/g, ' ');
}

/**
 * Record a message the customer sent to us.
 * @param {string} userId
 * @param {string} text raw message body as typed
 * @param {Date} at time the message was received
 */
export function onInbound(userId, text, at) {
  if (typeof userId !== 'string' || userId === '') {
    throw new TypeError('userId must be a non-empty string');
  }
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (!(at instanceof Date) || Number.isNaN(at.getTime())) {
    throw new TypeError('at must be a valid Date');
  }

  const customer = getCustomer(userId);
  const word = normalize(text);

  if (STOP_KEYWORDS.has(word)) {
    customer.optedOut = true;
  } else if (customer.optedOut && START_KEYWORDS.has(word)) {
    customer.optedOut = false;
  }

  // Keep the latest inbound time, so out-of-order delivery cannot shrink the window.
  const ts = at.getTime();
  if (customer.lastInbound === null || ts > customer.lastInbound) {
    customer.lastInbound = ts;
  }
}

/**
 * Decide whether the assistant may send a follow-up now.
 * @param {string} userId
 * @param {'freeform' | 'template'} type
 * @param {Date} now
 * @returns {{ allowed: boolean, rule: string | null }}
 */
export function check(userId, type, now) {
  if (
    typeof userId !== 'string' || userId === '' ||
    !TYPES.has(type) ||
    !(now instanceof Date) || Number.isNaN(now.getTime())
  ) {
    return { allowed: false, rule: 'invalid-input' };
  }

  const customer = customers.get(userId);

  if (customer?.optedOut) {
    return { allowed: false, rule: 'opted-out' };
  }
  if (!customer || customer.lastInbound === null) {
    return { allowed: false, rule: 'no-prior-inbound' };
  }
  if (type === 'freeform' && now.getTime() - customer.lastInbound >= WINDOW_MS) {
    return { allowed: false, rule: 'outside-24h-window' };
  }
  return { allowed: true, rule: null };
}

input.command:
mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { onInbound, check } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g5-3/bot.mjs';

const H = 3600_000;
const t0 = new Date('2026-10-23T10:00:00Z');
const at = (h) => new Date(t0.getTime() + h * H);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log('ok -', name); };

ok('never-written user is blocked for both types', () => {
  assert.deepEqual(check('new', 'freeform', at(0)), { allowed: false, rule: 'no-prior-inbound' });
  assert.deepEqual(check('new', 'template', at(0)), { allowed: false, rule: 'no-prior-inbound' });
});

onInbound('u1', 'Hi, my bill is wrong', at(0));
ok('freeform allowed inside 24h', () => {
  assert.deepEqual(check('u1', 'freeform', at(23.9)), { allowed: true, rule: null });
});
ok('freeform blocked at exactly 24h', () => {
  assert.deepEqual(check('u1', 'freeform', at(24)), { allowed: false, rule: 'outside-24h-window' });
});
ok('template allowed outside window', () => {
  assert.deepEqual(check('u1', 'template', at(100)), { allowed: true, rule: null });
});
ok('invalid input fails closed', () => {
  assert.deepEqual(check('u1', 'sms', at(1)), { allowed: false, rule: 'invalid-input' });
  assert.deepEqual(check('u1', 'freeform', new Date('x')), { allowed: false, rule: 'invalid-input' });
});

// STOP variants: case, punctuation, spaces, emoji, NBSP, zero-width chars
for (const v of ['STOP', ' stop ', 'Stop!', '  "STOP."  ', 'stop 🛑', 'S​TOP', 'stop ', 'UNSUBSCRIBE', 'stopall', 'Cancel', 'quit', 'END']) {
  ok(`opt-out keyword ${JSON.stringify(v)}`, () => {
    onInbound('u2', 'hello', at(0));
    onInbound('u2', v, at(1));
    assert.equal(check('u2', 'template', at(2)).rule, 'opted-out');
    assert.equal(check('u2', 'freeform', at(2)).rule, 'opted-out');
  });
}

ok('ordinary sentence with keyword is not opt-out', () => {
  onInbound('u3', 'hi', at(0));
  for (const v of ['please stop texting me', 'can you cancel my appointment?', 'stop the internet is down', 'the end']) {
    onInbound('u3', v, at(1));
  }
  assert.deepEqual(check('u3', 'freeform', at(2)), { allowed: true, rule: null });
});

ok('opt-out is sticky across other messages', () => {
  onInbound('u4', 'hi', at(0));
  onInbound('u4', 'STOP', at(1));
  onInbound('u4', 'thanks anyway', at(2));
  assert.equal(check('u4', 'template', at(3)).rule, 'opted-out');
});

ok('START resubscribes; then window still applies', () => {
  onInbound('u4', 'start', at(4));
  assert.deepEqual(check('u4', 'template', at(5)), { allowed: true, rule: null });
  assert.deepEqual(check('u4', 'freeform', at(5)), { allowed: true, rule: null });
  assert.equal(check('u4', 'freeform', at(30)).rule, 'outside-24h-window');
});

ok('UNSTOP and YES resubscribe, with punctuation', () => {
  onInbound('u5', 'stop', at(0));
  onInbound('u5', 'UNSTOP!', at(1));
  assert.equal(check('u5', 'template', at(2)).allowed, true);
  onInbound('u5', 'stop', at(3));
  onInbound('u5', ' yes. ', at(4));
  assert.equal(check('u5', 'template', at(5)).allowed, true);
});

ok('START while not opted out does not change state', () => {
  onInbound('u6', 'start', at(0));
  assert.equal(check('u6', 'freeform', at(1)).rule, null);
  assert.equal(check('u6', 'freeform', at(1)).allowed, true);
});

ok('out-of-order inbound does not shrink the window', () => {
  onInbound('u7', 'hi', at(10));
  onInbound('u7', 'old message', at(0));
  assert.equal(check('u7', 'freeform', at(30)).allowed, true);
});

ok('onInbound rejects bad args', () => {
  assert.throws(() => onInbound('', 'x', at(0)), TypeError);
  assert.throws(() => onInbound('u8', null, at(0)), TypeError);
  assert.throws(() => onInbound('u8', 'x', '2026-01-01'), TypeError);
});

ok('users are independent', () => {
  assert.equal(check('u1', 'template', at(1)).allowed, true);
  assert.equal(check('u2', 'template', at(1)).rule, 'opted-out');
});

console.log(`\n${n} groups passed`);
EOF
node /tmp/bot-test/test.mjs
